import re
from pathlib import Path
s=Path('tmp/pdfs/manuscript.txt').read_text()
for page in [19,20]:
    block=s.split(f'===== PAGE {page} =====')[1].split('Table '+str(11 if page==19 else 13)+':')[0]
    methods={'G-Eval': [], 'CheckEval': []}
    for line in block.splitlines():
        nums=list(map(float,re.findall(r'-?\\d+\\.\\d{4}',line)))
        if len(nums)"'!=10:continue
        for method in methods:
            if method in line: methods[method].append(nums[-2:])
    print('"'Page',page,'Spearman wins:',sum(c[0]>g[0] for g,c in zip(methods['G-Eval'],methods['CheckEval'])))
print('Possible naturalness scores near 0.88 with 28 binary questions:',[(k,round(k/28,4)) for k in range(23,27)])
try:
    from scipy.stats import ranksums,wilcoxon
    for page in [19,20]:
        block=s.split(f'===== PAGE {page} =====')[1].split('Table '+str(11 if page==19 else 13)+':')[0]
        methods={'G-Eval': [], 'CheckEval': []}
        for line in block.splitlines():
            nums=list(map(float,re.findall(r'-?\\d+\\.\\d{4}',line)))
            if len(nums)"'!=10: continue
            for method in methods:
                if method in line: methods[method].append(nums[-2:])
        for i in [0,1]:
            g=[r[i] for r in methods['"'G-Eval']]
            c=[r[i] for r in methods['CheckEval']]
            print(page,i,'ranksum p',ranksums(g,c).pvalue,'paired p',wilcoxon(g,c).pvalue)
except ImportError:
    print('scipy unavailable; no statistical test run')
